# A pessoa escolhe entre as suas ofertas de contrato, renovações incluídas (CONTRACT_MANAGER::resolve_contract_offers
# 0x4ce4e0, contract_manager.cpp; leitor D2 do fechamento do mapa do mercado, 11/11/2026). Chamada pela
# process_due_decision_dates (0x4cd9c0, Rust) quando vence uma data de decisão do tipo 3 (o passe diário dos contratos
# 0x4c7ac0). Igual no cm0102-1080.exe (0xfb6 bytes conferidos). Convenções conferidas na desmontagem:
# - a rotina: thiscall(gerente de contratos, pessoa), ret 4, quadro SEH (sem retorno);
# - 0x8cd150 / 0x8c5410 / 0x8c38b0: push x; mov ecx, [0xde1f54] -> thiscall ret 4; 0x8c28c0: push melhor; push vaga;
#   push pessoa -> ret 0xc; 0x8c2180: push lista; push dword do cargo (+0x61); push cópia; push vaga; push pessoa ->
#   ret 0x14; 0x8c61e0 ecx = [0xde1f54] e 0x8e82f0 ecx = [vaga], push pessoa -> ret 4;
# - 0x846920 / 0x849f00 / 0x844780: ecx = [[0xde1f54]+0x856] (o gerente de listas), ret 0x18 / 0xc / 0x14;
# - 0x85fc50: ecx = contrato desejado local, push 0; push 0; push cargo; push estatuto; push -1; push clube;
#   push pessoa -> ret 0x1c; 0x866830 ecx = contrato, push desejado; push pessoa -> ret 8;
# - 0x7a6e20 / 0x7a6e30: ecx = [0xb7434c]; 0x7549b0: ecx = [0xb6b7c8]; 0x69fc60: ecx = [0xb67a44]; 0x8b2880: ecx =
#   [0xde1f44]; 0x7f7270: ecx = [0xb74448]; 0x4d49a0 e 0x4d0c60: ecx = o gerente de contratos;
# - cdecl: 0x53b610, 0x53b620, 0x600a50, 0x90cfc0, 0x547a10, 0x547d90.
# Comparador: só a original roda (aloca, sorteia, assina); o plano é a avaliação da cópia sem listas (nada removido,
# o gerador e as datas estáticas restaurados) e, depois da original, o contrato da pessoa e o bit 0x80 do registro de
# 79 bytes têm de bater com a escolha do plano.
